 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Horizontal 5-bars extend an attached perpendicular color sequence
    # across the bar. The sequence is attached below/above one end.
    for r in range(h):
        cs = [c for c in range(w) if g[r][c] == 5]
        if not cs:
            continue
        # Work with maximal contiguous runs (ignore isolated 5s).
        runs = []
        start = prev = cs[0]
        for c in cs[1:]:
            if c != prev + 1:
                runs.append((start, prev))
                start = c
            prev = c
        runs.append((start, prev))
        for left, right in runs:
            if right - left < 1:
                continue
            for anchor in (left, right):
                for dr in (-1, 1):
                    rr = r + dr
                    vals = []
                    while 0 <= rr < h and g[rr][anchor] not in (0, 5):
                        vals.append(g[rr][anchor])
                        rr += dr
                    if vals:
                        rows = [r + dr * (i + 1) for i in range(len(vals))]
                        for c in range(left, right + 1):
                            for y, v in zip(rows, vals):
                                g[y][c] = v

    # Vertical 5-bars extend an attached horizontal color tile along the bar.
    # Capture the contiguous side block (which may be multiple rows tall),
    # then repeat it, aligned to the block's original position.
    for c in range(w):
        rs = [r for r in range(h) if g[r][c] == 5]
        if not rs:
            continue
        runs = []
        start = prev = rs[0]
        for r in rs[1:]:
            if r != prev + 1:
                runs.append((start, prev))
                start = r
            prev = r
        runs.append((start, prev))
        for top, bottom in runs:
            if bottom - top < 1:
                continue
            for side in (-1, 1):
                edge = c + side
                if not (0 <= edge < w):
                    continue
                # Find contiguous nonzero row-runs next to the bar.
                candidates = []
                r = top
                while r <= bottom:
                    if g[r][edge] in (0, 5):
                        r += 1
                        continue
                    a = r
                    while r <= bottom and g[r][edge] not in (0, 5):
                        r += 1
                    candidates.append((a, r - 1))
                if not candidates:
                    continue
                # The attached tile is the run nearest the end of the 5-bar.
                a, b = max(candidates, key=lambda x: x[1])
                width = 0
                while edge + side * width >= 0 and edge + side * width < w and g[a][edge + side * width] not in (0, 5):
                    width += 1
                if width == 0:
                    continue
                tile = [[g[y][edge + side * x] for x in range(width)] for y in range(a, b + 1)]
                period = len(tile)
                for y in range(top, bottom + 1):
                    # Preserve the phase of the original attached tile.
                    source_row = (y - a) % period
                    for x in range(width):
                        dest = edge + side * x
                        if 0 <= dest < w:
                            g[y][dest] = tile[source_row][x]
    return g
